import java.util.Arrays;
class Solution {
    public String solution(String number, int k) {
        String answer = "";
        StringBuffer snum = new StringBuffer(number);
        int start = 0;
        int i = 0;
        
        while(k>0){
            boolean flag = true;
            for(i = start; i<snum.length()-1; i++){
                if(snum.charAt(i)=='9'){ // 1
